public static String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }
    StringBuilder sb = new StringBuilder();
    char[] chars = str.toCharArray();
    for (int i = 0; i < chars.length; i++) {
        char c = chars[i];
        switch (c) {
            case '\\': {
                char nextChar = i < chars.length - 1 ? chars[i + 1] : '\0';
                switch (nextChar) {
                    case '\"':
                    case '\'':
                    case '\\':
                    case '/':
                    case 'b':
                    case 'f':
                    case 't':
                        break;
                    case 'n':
                        sb.append('\n');
                        break;
                    case 'r':
                        sb.append('\r');
                        break;
                    case 'u':
                        if (i + 4 < chars.length) {
                            int codePoint = ((chars[i + 1] & 0xff) << 12) |
                                        ((chars[i + 2] & 0xff) << 8) |
                                        ((chars[i + 3] & 0xff) << 4) |
                                        ((chars[i + 4] & 0xff));
                            sb.append((char) codePoint);
                            i += 4;
                        } else {
                            throw new IllegalArgumentException("Invalid Unicode \\u sequence");
                        }
                        break;
                }
                i++; // Skip the escaped character
                break;
            }
            default:
                sb.append(c);
                break;
        }
    }
    return sb.toString();
}

