public static String applyRelativePath(String path, String relativePath) {
    // Split the original path into parts
    String[] parts1 = path.split("/");
    String[] parts2 = relativePath.split("/");
    int maxLength = Math.max(parts1.length, parts2.length);

    // Construct the final path
   StringBuilder finalPath = new StringBuilder();
    for (int i = 0; i < maxLength; i++) {
        if (i < parts1.length && parts1[i].isEmpty()) {
            continue;
        }
        if (i < parts2.length && parts2[i].isEmpty()) {
            continue;
        }
        finalPath.append(parts1[i]);
        if (i < maxLength && !parts2[i].isEmpty()) {
            finalPath.append("/");
            finalPath.append(parts2[i]);
        }
    }

    // Remove any trailing slashes
    finalPath = new StringBuilder(finalPath.toString().replaceAll("/+$", ""));

    return finalPath.toString();
}

